    paths: Type.Array(AbsolutePathSchema, {minItems: 1}),
});

type FsCompressionJobCreation = Static<typeof FsCompressionJobCreationSchema>;

/**
 * Schema for request to create a new S3 compression job.
 *
 * When `scanner` is true, the request is forwarded to the log-ingestor as an
 * S3 scanner ingestion job instead of a one-time compression job.
 */
const S3CompressionJobCreationSchema = Type.Object({
    ...clpSJobCreationFields,
    bucket: Type.String({minLength: 1}),
    bufferChannelCapacity: Type.Optional(Type.Number({minimum: 1})),
    bufferFlushThresholdBytes: Type.Optional(Type.Number({minimum: 1})),
    bufferTimeoutSec: Type.Optional(Type.Number({minimum: 1})),
    inputType: Type.Literal(CompressionJobInputType.S3),
    keyPrefix: Type.Optional(Type.String()),
    keys: Type.Optional(Type.Array(Type.String({minLength: 1}), {minItems: 1})),
    regionCode: Type.String({minLength: 1}),
    scanner: Type.Boolean(),
    scanningIntervalSec: Type.Optional(Type.Number({minimum: 1})),
});

type S3CompressionJobCreation = Static<typeof S3CompressionJobCreationSchema>;

/**
 * Schema for request to create a new compression job (FS or S3).
 */
const CompressionJobCreationSchema = Type.Union([
    FsCompressionJobCreationSchema,
    S3CompressionJobCreationSchema,
]);

type CompressionJobCreation = Static<typeof CompressionJobCreationSchema>;

/**
 * Schema for compression job response.
 */
const CompressionJobSchema = Type.Object({
    jobId: Type.Number(),
});

type CompressionJob = Static<typeof CompressionJobSchema>;

/**
 * Schema for S3 scanner job creation response.
 */
const ScannerJobResponseSchema = Type.Object({
    jobIds: Type.Array(Type.Number()),
});

type ScannerJobResponse = Static<typeof ScannerJobResponseSchema>;


const clpSInputConfigFields = {
    dataset: Type.Union([Type.String(),
        Type.Null()]),
    timestamp_key: Type.Union([Type.String(),
        Type.Null()]),
    unstructured: Type.Boolean(),
};

/**
 * Matching `FsInputConfig` in `job_orchestration.scheduler.job_config`.
 */
const ClpIoFsInputConfigSchema = Type.Object({
    ...clpSInputConfigFields,
    path_prefix_to_remove: Type.Union([Type.String(),
        Type.Null()]),
    paths_to_compress: Type.Array(Type.String()),
    type: Type.Literal(CompressionJobInputType.FS),
});

type ClpIoFsInputConfig = Static<typeof ClpIoFsInputConfigSchema>;

/**
 * Matching `S3InputConfig` in `job_orchestration.scheduler.job_config`.
 * Includes fields inherited from `S3Config` in `clp_py_utils.clp_config`.
 */
const ClpIoS3InputConfigSchema = Type.Object({
    ...clpSInputConfigFields,
    aws_authentication: AwsAuthenticationSchema,
    bucket: Type.String(),
    key_prefix: Type.String(),
    keys: Type.Union([Type.Array(Type.String()),
        Type.Null()]),
    region_code: Type.Union([Type.String(),
        Type.Null()]),
    type: Type.Literal(CompressionJobInputType.S3),
});

type ClpIoS3InputConfig = Static<typeof ClpIoS3InputConfigSchema>;

/**
 * Matching `S3ObjectMetadataInputConfig` in `job_orchestration.scheduler.job_config`.
 */
const ClpIoS3ObjectMetadataInputConfigSchema = Type.Object({
    dataset: Type.Union([Type.String(),
        Type.Null()]),
    timestamp_key: Type.Union([Type.String(),
        Type.Null()]),
    type: Type.Literal(CompressionJobInputType.S3_OBJECT_METADATA),
    unstructured: Type.Boolean(),
});

/**
 * Matching `OutputConfig` in `job_orchestration.scheduler.job_config`.
 */
const ClpIoOutputConfigSchema = Type.Object({
    compression_level: Type.Number(),
    target_archive_size: Type.Number(),
    target_dictionaries_size: Type.Number(),
    target_encoded_file_size: Type.Number(),
    target_segment_size: Type.Number(),
});

/**
 * Matching `ClpIoConfig` in `job_orchestration.scheduler.job_config`.
 */
const ClpIoConfigSchema =
    Type.Object({
        input: Type.Union([
            ClpIoFsInputConfigSchema,
            ClpIoS3InputConfigSchema,
            ClpIoS3ObjectMetadataInputConfigSchema,
        ]),
        output: ClpIoOutputConfigSchema,
    });

type ClpIoConfig = Static<typeof ClpIoConfigSchema>;

/**
 * Less strict version of `ClpIoConfigSchema` to prevent Fastify validation errors
 * for compression metadata from older CLP releases with missing data.
 */
const ClpIoPartialConfigSchema =
    Type.Object({
        input: Type.Union([Type.Partial(ClpIoFsInputConfigSchema),
            Type.Partial(ClpIoS3InputConfigSchema),
            Type.Partial(ClpIoS3ObjectMetadataInputConfigSchema)]),
        output: Type.Partial(ClpIoOutputConfigSchema),
    });

export {
    ClpIoConfigSchema,
    ClpIoPartialConfigSchema,
    CompressionJobCreationSchema,
    CompressionJobInputType,
    CompressionJobSchema,
    DATASET_NAME_MAX_LEN,
    DATASET_NAME_PATTERN,
    DatasetNameSchema,
    ScannerJobResponseSchema,
};
export type {
    ClpIoConfig,
    ClpIoFsInputConfig,
    ClpIoS3InputConfig,
    CompressionJob,
    CompressionJobCreation,
    FsCompressionJobCreation,
    S3CompressionJobCreation,
    ScannerJobResponse,
};

import {
    useMutation,
    useQueryClient,
} from "@tanstack/react-query";
import {
    CLP_STORAGE_ENGINES,
    STORAGE_TYPE,
} from "@webui/common/config";
import {
    CompressionJobInputType,
    FsCompressionJobCreation,
} from "@webui/common/schemas/compression";
import {
    Col,
    Form,
    Input,
    Radio,
    Row,
    Typography,
} from "antd";

import {
    submitCompressionJob,
    submitScannerJob,
} from "../../../api/compress";
import {DashboardCard} from "../../../components/DashboardCard";
import {
    SETTINGS_LOGS_INPUT_TYPE,
    SETTINGS_STORAGE_ENGINE,
} from "../../../config";
import ClpSFormItems from "./ClpSFormItems";
import {
    LOGS_TYPE_HELPER_TEXT,
    TIMESTAMP_KEY_HELPER_TEXT,
} from "./formConstants";
import {
    applyClpSFields,
    buildS3Payload,
    filterValidS3Paths,
    getSuccessMessage,
    type SubmitResult,
} from "./jobHelpers";
import PathsSelectFormItem from "./PathsSelectFormItem";
import S3InputFormItems from "./S3InputFormItems";
import ScannerAdvancedFormItems from "./ScannerAdvancedFormItems";
import SubmitFormItem from "./SubmitFormItem";


type FormValues = {
    bucket?: string;
    bufferChannelCapacity?: number;
    bufferFlushThresholdBytes?: number;
    bufferTimeoutSec?: number;
    dataset?: string;
    ingestMode?: string;
    paths?: string[];
    regionCode?: string;
    s3Paths?: string[];
    scanningIntervalSec?: number;
    timestampKey?: string;
    unstructured?: boolean;
};

const isS3Input = STORAGE_TYPE.S3 === SETTINGS_LOGS_INPUT_TYPE;
const INGEST_MODE_ONE_TIME = "one-time";
const INGEST_MODE_SCANNER = "scanner";
const showClpSFields = CLP_STORAGE_ENGINES.CLP_S === SETTINGS_STORAGE_ENGINE;
const TIMESTAMP_KEY_PLACEHOLDER =
    "The path (e.g. x.y) for the field containing the log event's timestamp";
const RADIO_BUTTON_STYLE = {width: "50%", textAlign: "center" as const};

/**
 * Builds and submits the appropriate job based on form values.
 *
 * @param values
 * @return
 */
const submitJob = async (values: FormValues): Promise<SubmitResult> => {
    const isScanner = isS3Input && INGEST_MODE_SCANNER === values.ingestMode;

    if (isS3Input) {
        const payload = buildS3Payload({
            bucket: values.bucket as string,
            regionCode: values.regionCode as string,
            s3Paths: filterValidS3Paths(values.s3Paths),
            scanner: isScanner,
            values: values,
        });

        if (isScanner) {
            const result = await submitScannerJob(payload);

            return {jobIds: result.jobIds, type: "scanner"};
        }

        const result = await submitCompressionJob(payload);

        return {jobId: result.jobId, type: "compression"};
    }

    const fsPayload: FsCompressionJobCreation = {
        inputType: CompressionJobInputType.FS,
        paths: values.paths as string[],
    };

    if (showClpSFields) {
        applyClpSFields(fsPayload, values);
    }

    const result = await submitCompressionJob(fsPayload);

    return {jobId: result.jobId, type: "compression"};
};

/**
 * Renders submit result feedback.
 *
 * @param isSuccess
 * @param isError
 * @param data
 * @param error
 * @return
 */
const renderFeedback = (
    isSuccess: boolean,
    isError: boolean,
    data: SubmitResult | undefined,
    error: Error | null,
) => {
    if (isSuccess) {
        return (
            <Typography.Text type={"success"}>
                {getSuccessMessage(data as SubmitResult)}
            </Typography.Text>
        );
    }
    if (isError) {
        return (
            <Typography.Text type={"danger"}>
                {"Failed to submit job: "}
                {error instanceof Error ?
                    error.message :
                    "Unknown error"}
            </Typography.Text>
        );
    }

    return null;
};

/**
 * Renders a compression job submission form.
 *
 * @return
 */
const Compress = () => {
    const [form] = Form.useForm<FormValues>();
    const ingestMode = Form.useWatch("ingestMode", form);
    const unstructured = Form.useWatch<boolean>("unstructured", form);
    const isScanner = isS3Input && INGEST_MODE_SCANNER === ingestMode;
    const queryClient = useQueryClient();
    const {
        mutate,
        isPending: isSubmitting,
        isSuccess,
        isError,
        data,
        error,
    } = useMutation({
        mutationFn: submitJob,
        onSettled: async () => {
            await queryClient.invalidateQueries({queryKey: ["jobs"]});
        },
        onSuccess: () => {
            form.resetFields();
        },
    });

    return (
        <DashboardCard title={"Submit Compression Job"}>
            <Form
                form={form}
                layout={"vertical"}
                requiredMark={"optional"}
                onFinish={mutate}
            >
                {isS3Input && (
                    <Row gutter={8}>
                        <Col span={5}>
                            <Form.Item
                                initialValue={INGEST_MODE_ONE_TIME}
                                label={"Job Type"}
                                name={"ingestMode"}
                                required={true}
                                tooltip={
                                    "Scanner: continuously polls S3 for new objects and" +
                                    " compresses them automatically."
                                }
                            >
                                <Radio.Group style={{width: "100%"}}>
                                    <Radio.Button
                                        style={RADIO_BUTTON_STYLE}
                                        value={INGEST_MODE_ONE_TIME}
                                    >
                                        One-time
                                    </Radio.Button>
                                    <Radio.Button
                                        style={RADIO_BUTTON_STYLE}
                                        value={INGEST_MODE_SCANNER}
                                    >
                                        Scanner
                                    </Radio.Button>
                                </Radio.Group>
                            </Form.Item>
                        </Col>
                    </Row>
                )}
                {showClpSFields && (
                    <Row gutter={8}>
                        <Col span={5}>
                            <Form.Item
                                initialValue={false}
                                label={"Logs Type"}
                                name={"unstructured"}
                                required={true}
                                tooltip={LOGS_TYPE_HELPER_TEXT}
                            >
                                <Radio.Group style={{width: "100%"}}>
                                    <Radio.Button
                                        style={RADIO_BUTTON_STYLE}
                                        value={false}
                                    >
                                        JSON
                                    </Radio.Button>
                                    <Radio.Button
                                        style={RADIO_BUTTON_STYLE}
                                        value={true}
                                    >
                                        Text
                                    </Radio.Button>
                                </Radio.Group>
                            </Form.Item>
                        </Col>
                        <Col span={19}>
                            <Form.Item
                                label={"Timestamp Key"}
                                name={"timestampKey"}
                                tooltip={TIMESTAMP_KEY_HELPER_TEXT}
                            >
                                <Input
                                    disabled={unstructured}
                                    placeholder={TIMESTAMP_KEY_PLACEHOLDER}/>
                            </Form.Item>
                        </Col>
                    </Row>
                )}
                {isS3Input ?
                    <S3InputFormItems isScanner={isScanner}/> :
                    <PathsSelectFormItem/>}
                {showClpSFields && <ClpSFormItems/>}
                {isScanner && <ScannerAdvancedFormItems/>}
                <SubmitFormItem isSubmitting={isSubmitting}/>
                {renderFeedback(isSuccess, isError, data, error)}
            </Form>
        </DashboardCard>
    );
};

export default Compress;

import {Hono} from "hono";
import type {TSchema} from "@sinclair/typebox";
import {tbValidator} from "@hono/typebox-validator";
import {
  CreateDashboardSchema,
  type CreateDashboardRequest,
  UpdateDashboardSchema,
  type UpdateDashboardRequest,
} from "@webui/common/dashboard/schemas";
import type {Annotation, Dashboard} from "@webui/common/dashboard/types";
import {nanoid} from "nanoid";
import type {DashboardStorage} from "../storage/dashboard-storage.js";
import {InMemoryDashboardStorage} from "../storage/dashboard-storage.js";
import {toMySQLDatetime} from "../storage/datetime-utils.js";

/** Dashboard storage (swappable: in-memory for dev, MySQL for production) */
let storage: DashboardStorage = new InMemoryDashboardStorage();

export function setDashboardStorage(s: DashboardStorage): void {
  storage = s;
}

function generateUid(): string {
  return nanoid(10);
}

/** Dashboard CRUD routes (Hono, chained for RPC type inference) */
export const dashboardRoutes = new Hono()
  .get("/", async (c): Promise<Response> => {
    const dashboards = await storage.list();
    return c.json(dashboards);
  })
  .post("/", tbValidator("json", CreateDashboardSchema as unknown as TSchema), async (c) => {
    const body = c.req.valid("json") as CreateDashboardRequest;
    const now = toMySQLDatetime();
    const dashboard: Dashboard = {
      id: nanoid(21),
      uid: body.uid ?? generateUid(),
      title: body.title,
      tags: body.tags ?? [],
      variables: body.variables ?? [],
      timeRange: body.timeRange ?? {from: "now-6h", to: "now"},
      panels: body.panels ?? [],
      version: 1,
      updatedAt: now,
      createdAt: now,
    };
    if (body.description !== undefined) {
      dashboard.description = body.description;
    }
    if (body.refreshInterval !== undefined) {
      dashboard.refreshInterval = body.refreshInterval;
    }
    await storage.create(dashboard);
    return c.json(dashboard, 201);
  })
  .get("/:uid", async (c) => {
    const {uid} = c.req.param();
    const dashboard = await storage.get(uid);
    if (!dashboard) {
      return c.json({error: "Dashboard not found"}, 404);
    }
    return c.json(dashboard);
  })
  .put("/:uid", tbValidator("json", UpdateDashboardSchema as unknown as TSchema), async (c) => {
    const {uid} = c.req.param();
    const existing = await storage.get(uid);
    if (!existing) {
      return c.json({error: "Dashboard not found"}, 404);
    }
    const body = c.req.valid("json") as UpdateDashboardRequest;

    // Optimistic concurrency check
    if (body.version !== existing.version) {
      return c.json({error: "Version conflict", currentVersion: existing.version}, 409);
    }

    const updated: Dashboard = {
      ...existing,
      title: body.title ?? existing.title,
      tags: body.tags ?? existing.tags,
      variables: body.variables ?? existing.variables,
      timeRange: body.timeRange ?? existing.timeRange,
      panels: body.panels ?? existing.panels,
      version: existing.version + 1,
      updatedAt: toMySQLDatetime(),
    };
    if (body.description !== undefined) {
      updated.description = body.description;
    }
    if (body.refreshInterval !== undefined) {
      updated.refreshInterval = body.refreshInterval;
    }
    if (body.tabs !== undefined) {
      updated.tabs = body.tabs;
    }
    const result = await storage.update(uid, updated);
    if (!result) {
      return c.json({error: "Update failed - version conflict"}, 409);
    }
    return c.json(updated);
  })
  .delete("/:uid", async (c) => {
    const {uid} = c.req.param();
    const deleted = await storage.delete(uid);
    if (!deleted) {
      return c.json({error: "Dashboard not found"}, 404);
    }
    return c.json({success: true}, 200);
  })
  .post("/:uid/duplicate", async (c) => {
    const {uid} = c.req.param();
    const existing = await storage.get(uid);
    if (!existing) {
      return c.json({error: "Dashboard not found"}, 404);
    }
    const now = toMySQLDatetime();
    const duplicate: Dashboard = {
      ...existing,
      id: nanoid(21),
      uid: generateUid(),
      title: `${existing.title} (Copy)`,
      version: 1,
      updatedAt: now,
      createdAt: now,
    };
    await storage.create(duplicate);
    return c.json(duplicate, 201);
  })
  .post("/bulk-delete", async (c) => {
    const body = await c.req.json();
    const uids = body.uids as string[];
    if (!Array.isArray(uids) || uids.length === 0) {
      return c.json({error: "uids array is required"}, 400);
    }
    const results = await Promise.allSettled(uids.map((uid: string) => storage.delete(uid)));
    const deleted = results.filter((r) => r.status === "fulfilled" && r.value).length;
    const failed = results.length - deleted;
    return c.json({deleted, failed});
  })
  // Annotation CRUD
  .get("/:uid/annotations", async (c) => {
    const {uid} = c.req.param();
    const dashboard = await storage.get(uid);
    if (!dashboard) {
      return c.json({error: "Dashboard not found"}, 404);
    }
    return c.json(dashboard.annotations ?? []);
  })
  .post("/:uid/annotations", async (c) => {
    const {uid} = c.req.param();
    const dashboard = await storage.get(uid);
    if (!dashboard) {
      return c.json({error: "Dashboard not found"}, 404);
    }
    const body = await c.req.json();
    const annotation: Annotation = {
      id: nanoid(10),
      time: body.time,
      timeEnd: body.timeEnd,
      title: body.title ?? "",
      tags: body.tags,
      color: body.color,
    };
    const annotations = [...(dashboard.annotations ?? []), annotation];
    const updated: Dashboard = {
      ...dashboard,
      annotations,
      version: dashboard.version + 1,
      updatedAt: toMySQLDatetime(),
    };
    await storage.update(uid, updated);
    return c.json(annotation, 201);
  })
  .delete("/:uid/annotations/:annotationId", async (c) => {
    const {uid, annotationId} = c.req.param();
    const dashboard = await storage.get(uid);
    if (!dashboard) {
      return c.json({error: "Dashboard not found"}, 404);
    }
    const annotations = (dashboard.annotations ?? []).filter((a) => a.id !== annotationId);
    const updated: Dashboard = {
      ...dashboard,
      annotations,
      version: dashboard.version + 1,
      updatedAt: toMySQLDatetime(),
    };
    await storage.update(uid, updated);
    return c.json({success: true});
  });

export type DashboardRoutesType = typeof dashboardRoutes;

import {CLP_QUERY_ENGINES} from "@webui/common/config";

import {SETTINGS_QUERY_ENGINE} from "../../config";
import styles from "./index.module.css";
import {ProgressBar} from "./ProgressBar";
import SearchControls from "./SearchControls";
import SearchResultsTable from "./SearchResults/SearchResultsTable";
import SearchResultsTimeline from "./SearchResults/SearchResultsTimeline";
import usePrestoSearchState from "./SearchState/Presto";
import {PRESTO_SQL_INTERFACE} from "./SearchState/Presto/typings";
import {useUpdateStateWithMetadata} from "./SearchState/useUpdateStateWithMetadata";


/**
 * Provides a search interface that allows users to query archives and visualize search results.
 *
 * @return
 */
const SearchPage = () => {
    useUpdateStateWithMetadata();
    const sqlInterface = usePrestoSearchState((state) => state.sqlInterface);

    return (
        <>
            {SETTINGS_QUERY_ENGINE === CLP_QUERY_ENGINES.PRESTO && <ProgressBar/>}
            <div className={styles["searchPageContainer"]}>
                <SearchControls/>
                {(SETTINGS_QUERY_ENGINE !== CLP_QUERY_ENGINES.PRESTO ||
                  PRESTO_SQL_INTERFACE.GUIDED === sqlInterface) &&
                  <SearchResultsTimeline/>}
                <SearchResultsTable/>
            </div>
        </>
    );
};

export default SearchPage;

