import {useQuery} from "@tanstack/react-query";
import {hc} from "hono/client";
import {useState} from "react";

import {Badge} from "@/components/ui/badge";
import {Collapsible, CollapsibleContent, CollapsibleTrigger} from "@/components/ui/collapsible";
import {Input} from "@/components/ui/input";
import {ScrollArea} from "@/components/ui/scroll-area";
import {Separator} from "@/components/ui/separator";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/ui/table";

import type {AppType} from "@webui/server/hono-app";


type VariableInfo = {
    index: number;
    type: "string" | "int" | "float";
};

type LogtypeStat = {
    logtype: string;
    count: number;
    template: string;
    variables: VariableInfo[];
};

type SharedNodeWarning = {
    variableIndex: number;
    variableType: string;
    logtypes: string[];
    message: string;
};

type LogtypeStatsResponse = {
    archiveId: string;
    logtypes: LogtypeStat[];
    totalCount: number;
    sharedNodeWarnings: SharedNodeWarning[];
};

const api = hc<AppType>("/");

const VARIABLE_TYPE_COLORS: Record<string, string> = {
    int: "bg-blue-100 text-blue-800",
    float: "bg-purple-100 text-purple-800",
    string: "bg-green-100 text-green-800",
};

/**
 * Renders the Patterns tab showing logtype occurrence statistics
 * and shared node warnings.
 */
const PatternsTab = () => {
    const [search, setSearch] = useState("");
    const [expandedLogtype, setExpandedLogtype] = useState<string | null>(null);

    const {data, isLoading, error} = useQuery({
        queryKey: ["logtype-stats"],
        queryFn: async () => {
            const res = await api.api.logtype_stats.$get({
                query: {archive_id: "latest"},
            });
            return res.json() as Promise<LogtypeStatsResponse>;
        },
    });

    if (isLoading) {
        return <div className="p-4 text-sm text-muted-foreground">Loading logtype stats...</div>;
    }

    if (error) {
        return <div className="p-4 text-sm text-red-600">Error: {error.message}</div>;
    }

    if (!data) {
        return <div className="p-4 text-sm text-muted-foreground">No logtype data available.</div>;
    }

    const filtered = data.logtypes.filter(
        (lt) =>
            lt.logtype.toLowerCase().includes(search.toLowerCase()) ||
            lt.template.toLowerCase().includes(search.toLowerCase()),
    );

    return (
        <div className="flex flex-col gap-4">
            {0 < data.sharedNodeWarnings.length && (
                <div className="rounded-md border border-yellow-300 bg-yellow-50 p-3">
                    <p className="text-sm font-medium text-yellow-800">Shared Node Warnings</p>
                    <ul className="mt-1 list-inside list-disc text-sm text-yellow-700">
                        {data.sharedNodeWarnings.map((w, i) => (
                            <li key={i}>{w.message}</li>
                        ))}
                    </ul>
                </div>
            )}

            <Input
                placeholder="Search logtypes..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
            />

            <div className="text-sm text-muted-foreground">
                {filtered.length} logtype{1 !== filtered.length ? "s" : ""} | {data.totalCount.toLocaleString()} total events
            </div>

            <ScrollArea className="h-[calc(100vh-320px)]">
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead className="w-12"/>
                            <TableHead>Logtype</TableHead>
                            <TableHead className="text-right">Count</TableHead>
                            <TableHead>Template</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {filtered.map((lt) => {
                            const isExpanded = expandedLogtype === lt.logtype;
                            return (
                                <Collapsible
                                    key={lt.logtype}
                                    open={isExpanded}
                                    onOpenChange={() => setExpandedLogtype(isExpanded ? null : lt.logtype)}
                                    asChild
                                >
                                    <TableRow className="cursor-pointer">
                                        <TableCell>
                                            <CollapsibleTrigger asChild>
                                                <button className="text-muted-foreground hover:text-foreground">
                                                    {isExpanded ? "▼" : "▶"}
                                                </button>
                                            </CollapsibleTrigger>
                                        </TableCell>
                                        <TableCell className="font-mono text-xs">{lt.logtype}</TableCell>
                                        <TableCell className="text-right">{lt.count.toLocaleString()}</TableCell>
                                        <TableCell className="max-w-md truncate font-mono text-xs">
                                            {lt.template}
                                        </TableCell>
                                    </TableRow>
                                    {isExpanded && (
                                        <TableRow>
                                            <TableCell colSpan={4} className="bg-muted/50 px-8 py-3">
                                                <CollapsibleContent>
                                                    <div className="space-y-2">
                                                        <p className="text-xs font-medium">Variables ({lt.variables.length})</p>
                                                        <div className="flex flex-wrap gap-2">
                                                            {lt.variables.map((v) => (
                                                                <Badge
                                                                    key={v.index}
                                                                    variant="outline"
                                                                    className={VARIABLE_TYPE_COLORS[v.type] ?? ""}
                                                                >
                                                                    #{v.index} {v.type}
                                                                </Badge>
                                                            ))}
                                                        </div>
                                                        <Separator/>
                                                        <p className="text-xs text-muted-foreground">
                                                            Template: <code className="text-foreground">{lt.template}</code>
                                                        </p>
                                                    </div>
                                                </CollapsibleContent>
                                            </TableCell>
                                        </TableRow>
                                    )}
                                </Collapsible>
                            );
                        })}
                    </TableBody>
                </Table>
            </ScrollArea>
        </div>
    );
};


export {PatternsTab};
export default PatternsTab;

