import {useQuery} from "@tanstack/react-query";
import {hc} from "hono/client";
import {useState} from "react";

import {Badge} from "@/components/ui/badge";
import {Collapsible, CollapsibleContent, CollapsibleTrigger} from "@/components/ui/collapsible";
import {Input} from "@/components/ui/input";
import {ScrollArea} from "@/components/ui/scroll-area";

import type {AppType} from "@webui/server/hono-app";


type SchemaTreeNode = {
    id: string;
    key: string;
    type: "string" | "int" | "float" | "object";
    count: number;
    children: SchemaTreeNode[];
};

const api = hc<AppType>("/");

const TYPE_ICONS: Record<string, string> = {
    string: "Aa",
    int: "#",
    float: "~",
    object: "{}",
};

const TYPE_COLORS: Record<string, string> = {
    string: "bg-green-100 text-green-800",
    int: "bg-blue-100 text-blue-800",
    float: "bg-purple-100 text-purple-800",
    object: "bg-gray-100 text-gray-800",
};

/**
 * Renders a single node in the schema tree, recursively.
 */
const SchemaTreeNodeItem = ({
    node,
    depth = 0,
}: {
    node: SchemaTreeNode;
    depth?: number;
}) => {
    const [isOpen, setIsOpen] = useState(depth < 2);
    const hasChildren = 0 < node.children.length;

    return (
        <div>
            <Collapsible open={isOpen} onOpenChange={setIsOpen}>
                <div
                    className="flex items-center gap-2 rounded-sm px-2 py-1 hover:bg-muted/50"
                    style={{paddingLeft: `${depth * 20 + 8}px`}}
                >
                    {hasChildren ? (
                        <CollapsibleTrigger asChild>
                            <button className="w-4 text-muted-foreground hover:text-foreground">
                                {isOpen ? "▼" : "▶"}
                            </button>
                        </CollapsibleTrigger>
                    ) : (
                        <span className="w-4"/>
                    )}
                    <Badge
                        variant="outline"
                        className={`text-[10px] ${TYPE_COLORS[node.type] ?? ""}`}
                    >
                        {TYPE_ICONS[node.type] ?? "?"}
                    </Badge>
                    <span className="font-mono text-sm">{node.key}</span>
                    <span className="text-xs text-muted-foreground">
                        ({node.count.toLocaleString()})
                    </span>
                </div>
                {hasChildren && (
                    <CollapsibleContent>
                        {node.children.map((child) => (
                            <SchemaTreeNodeItem
                                key={child.id}
                                node={child}
                                depth={depth + 1}
                            />
                        ))}
                    </CollapsibleContent>
                )}
            </Collapsible>
        </div>
    );
};

/**
 * Renders the Schema tab showing the schema tree from an archive.
 */
const SchemaTab = () => {
    const [search, setSearch] = useState("");

    const {data, isLoading, error} = useQuery({
        queryKey: ["schema-tree"],
        queryFn: async () => {
            const res = await api.api.schema_tree.$get({
                query: {archive_id: "latest"},
            });
            return res.json() as Promise<{archiveId: string; tree: SchemaTreeNode}>;
        },
    });

    if (isLoading) {
        return <div className="p-4 text-sm text-muted-foreground">Loading schema tree...</div>;
    }

    if (error) {
        return <div className="p-4 text-sm text-red-600">Error: {error.message}</div>;
    }

    if (!data?.tree) {
        return <div className="p-4 text-sm text-muted-foreground">No schema tree data available.</div>;
    }

    return (
        <div className="flex flex-col gap-4">
            <Input
                placeholder="Filter schema nodes..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
            />

            <div className="text-sm text-muted-foreground">
                Schema tree for archive: <code>{data.archiveId}</code>
            </div>

            <ScrollArea className="h-[calc(100vh-280px)]">
                <div className="space-y-0.5">
                    <SchemaTreeNodeItem node={data.tree}/>
                </div>
            </ScrollArea>
        </div>
    );
};


export {SchemaTab};
export default SchemaTab;

