import {Badge} from "@/components/ui/badge";
import {Popover, PopoverContent, PopoverTrigger} from "@/components/ui/popover";

import {useClppSettingsStore} from "@/features/clpp/stores/clpp-settings-store";


/**
 * Badge indicating that a wildcard query matched a numeric (int/float) column.
 *
 * In CLPP, when a wildcard query like `*error*` matches integer or float
 * columns, the query engine applies the wildcard to the stringified numeric
 * value. This badge appears in search results to indicate this behavior.
 */
const WildcardOnNumericBadge = ({fieldName, fieldType}: {
    fieldName: string;
    fieldType: "int" | "float";
}) => {
    const experimentalMode = useClppSettingsStore((s) => s.experimentalMode);

    if (!experimentalMode) {
        return null;
    }

    return (
        <Popover>
            <PopoverTrigger asChild>
                <Badge
                    variant="outline"
                    className="cursor-pointer border-blue-300 bg-blue-50 text-[10px] text-blue-700"
                >
                    [i CLPP]
                </Badge>
            </PopoverTrigger>
            <PopoverContent className="w-64" side="top">
                <div className="space-y-1 text-xs">
                    <p className="font-medium">Wildcard-on-Numeric Match</p>
                    <p>
                        The wildcard query matched field <code>{fieldName}</code> which has
                        type <code>{fieldType}</code>. The wildcard was applied to the
                        stringified numeric value.
                    </p>
                </div>
            </PopoverContent>
        </Popover>
    );
};


export {WildcardOnNumericBadge};
export default WildcardOnNumericBadge;

