import {Hono} from "hono";
import type {TSchema} from "@sinclair/typebox";
import {tbValidator} from "@hono/typebox-validator";
import {Type} from "@sinclair/typebox";

const SchemaTreeQuerySchema = Type.Object({
  archive_id: Type.String({minLength: 1}),
});

// TypeBox doesn't cleanly support self-referencing schemas;
// use Type.Any() for children and rely on runtime structure.
const SchemaTreeNodeSchema = Type.Object({
  id: Type.String(),
  key: Type.String(),
  type: Type.Union([Type.Literal("string"), Type.Literal("int"), Type.Literal("float"), Type.Literal("object")]),
  count: Type.Number(),
  children: Type.Array(Type.Any()),
});

export const schemaTreeRoutes = new Hono()
  .get("/", tbValidator("query", SchemaTreeQuerySchema as unknown as TSchema), async (c) => {
    const {archive_id} = c.req.valid("query");

    const mockTree = {
      id: "root",
      key: "root",
      type: "object" as const,
      count: 16635,
      children: [
        {
          id: "var-0",
          key: "0",
          type: "string" as const,
          count: 16635,
          children: [
            {
              id: "var-0-app",
              key: "application_id",
              type: "string" as const,
              count: 15420,
              children: [],
            },
            {
              id: "var-0-container",
              key: "container_id",
              type: "string" as const,
              count: 873,
              children: [],
            },
            {
              id: "var-0-job",
              key: "job_id",
              type: "string" as const,
              count: 342,
              children: [],
            },
          ],
        },
        {
          id: "var-1",
          key: "1",
          type: "object" as const,
          count: 1215,
          children: [
            {
              id: "var-1-host",
              key: "host",
              type: "string" as const,
              count: 873,
              children: [],
            },
            {
              id: "var-1-exit-code",
