    const {archive_id} = c.req.valid("query");

    const mockResponse = {
      archiveId: archive_id,
      logtypes: [
        {
          logtype: "INFO ResourceManager: Application %VAR% is running on %VAR%",
          count: 15420,
          template: "INFO ResourceManager: Application %VAR% is running on %VAR%",
          variables: [
            {index: 0, type: "string" as const},
            {index: 1, type: "string" as const},
          ],
        },
        {
          logtype: "WARN NodeManager: Container %VAR% exceeded memory limit of %VAR% MB",
          count: 873,
          template: "WARN NodeManager: Container %VAR% exceeded memory limit of %VAR% MB",
          variables: [
            {index: 0, type: "string" as const},
            {index: 1, type: "int" as const},
          ],
        },
        {
          logtype: "ERROR JobHistoryServer: Job %VAR% failed with exit code %VAR% after %VAR% seconds",
          count: 342,
          template: "ERROR JobHistoryServer: Job %VAR% failed with exit code %VAR% after %VAR% seconds",
          variables: [
            {index: 0, type: "string" as const},
            {index: 1, type: "int" as const},
            {index: 2, type: "float" as const},
          ],
        },
      ],
      totalCount: 16635,
      sharedNodeWarnings: [
        {
          variableIndex: 0,
          variableType: "string",
          logtypes: [
            "INFO ResourceManager: Application %VAR% is running on %VAR%",
            "WARN NodeManager: Container %VAR% exceeded memory limit of %VAR% MB",
            "ERROR JobHistoryServer: Job %VAR% failed with exit code %VAR% after %VAR% seconds",
          ],
          message: "Variable at position 0 appears in 3 logtypes with consistent type (string). This creates a shared node in the schema tree.",
        },
        {
          variableIndex: 1,
          variableType: "mixed",
          logtypes: [
            "WARN NodeManager: Container %VAR% exceeded memory limit of %VAR% MB",
            "ERROR JobHistoryServer: Job %VAR% failed with exit code %VAR% after %VAR% seconds",
          ],
          message: "Variable at position 1 appears in 2 logtypes with inconsistent types (string, int). This creates a shared node in the schema tree that may cause ambiguous query results.",
        },
      ],
    };

    return c.json(mockResponse);
  });

export type LogtypeStatsRoutesType = typeof logtypeStatsRoutes;

