                                    {isExpanded && (
                                        <TableRow>
                                            <TableCell colSpan={4} className="bg-muted/50 px-8 py-3">
                                                <CollapsibleContent>
                                                    <div className="space-y-2">
                                                        <p className="text-xs font-medium">Variables ({lt.variables.length})</p>
                                                        <div className="flex flex-wrap gap-2">
                                                            {lt.variables.map((v) => (
