type SchemaTreeNode = {
    id: string;
    key: string;
    type: "string" | "int" | "float" | "object";
    count: number;
    children: SchemaTreeNode[];
};

const api = hc<AppType>("/");

const TYPE_ICONS: Record<string, string> = {
    string: "Aa",
    int: "#",
    float: "~",
    object: "{}",
};

const TYPE_COLORS: Record<string, string> = {
    string: "bg-green-100 text-green-800",
    int: "bg-blue-100 text-blue-800",
    float: "bg-purple-100 text-purple-800",
    object: "bg-gray-100 text-gray-800",
};

/**
 * Renders a single node in the schema tree, recursively.
 */
const SchemaTreeNodeItem = ({
    node,
    depth = 0,
}: {
    node: SchemaTreeNode;
    depth?: number;
}) => {
    const [isOpen, setIsOpen] = useState(depth < 2);
    const hasChildren = 0 < node.children.length;

    return (
        <div>
            <Collapsible open={isOpen} onOpenChange={setIsOpen}>
                <div
                    className="flex items-center gap-2 rounded-sm px-2 py-1 hover:bg-muted/50"
                    style={{paddingLeft: `${depth * 20 + 8}px`}}
                >
                    {hasChildren ? (
                        <CollapsibleTrigger asChild>
                            <button className="w-4 text-muted-foreground hover:text-foreground">
                                {isOpen ? "▼" : "▶"}
                            </button>
                        </CollapsibleTrigger>
                    ) : (
                        <span className="w-4"/>
                    )}
                    <Badge
                        variant="outline"
                        className={`text-[10px] ${TYPE_COLORS[node.type] ?? ""}`}
                    >
                        {TYPE_ICONS[node.type] ?? "?"}
                    </Badge>
                    <span className="font-mono text-sm">{node.key}</span>
                    <span className="text-xs text-muted-foreground">
                        ({node.count.toLocaleString()})
                    </span>
                </div>
                {hasChildren && (
                    <CollapsibleContent>
                        {node.children.map((child) => (
                            <SchemaTreeNodeItem
                                key={child.id}
                                node={child}
                                depth={depth + 1}
                            />
                        ))}
                    </CollapsibleContent>
                )}
            </Collapsible>
        </div>
    );
};

/**
