    NEXISTS: "NEXISTS",
    EQUALS: "==",
    NOT_EQUALS: "!=",
};

const FIELD_OPTIONS = [
    "message.application_id",
    "message.container_id",
    "message.job_id",
    "message.host",
    "message.exit_code",
    "timestamp",
    "level",
    "service",
];

/**
 * Filter bar with EXISTS/NEXISTS support for CLPP experimental queries.
 *
 * Caveat: EXISTS queries won't return results due to the KQL parser issue
 * in the C++ search backend. A warning is shown when EXISTS is selected.
 */
const FilterBar = ({
    filters,
    onAddFilter,
    onRemoveFilter,
}: {
    filters: Filter[];
    onAddFilter: (filter: Filter) => void;
    onRemoveFilter: (id: string) => void;
}) => {
    const experimentalMode = useClppSettingsStore((s) => s.experimentalMode);
    const [newField, setNewField] = useState<string>(FIELD_OPTIONS[0] ?? "");
    const [newType, setNewType] = useState<FilterType>("EXISTS");
    const [newValue, setNewValue] = useState("");

    const handleAdd = () => {
        const filter: Filter = {
            id: `${newField}-${newType}-${Date.now()}`,
            field: newField,
            type: newType,
        };
        if ("EXISTS" !== newType && "NEXISTS" !== newType) {
            filter.value = newValue;
        }
        onAddFilter(filter);
        setNewValue("");
    };

    return (
        <div className="flex flex-wrap items-center gap-2 border-b px-4 py-2">
            {filters.map((filter) => (
                <Badge key={filter.id} variant="secondary" className="gap-1">
                    <span className="font-mono text-xs">{filter.field}</span>
                    <span className="text-xs font-bold">{FILTER_TYPE_LABELS[filter.type]}</span>
                    {filter.value && (
                        <span className="font-mono text-xs">{filter.value}</span>
                    )}
                    <button
                        className="ml-1 rounded-full hover:bg-muted"
                        onClick={() => onRemoveFilter(filter.id)}
                    >
                        <X className="h-3 w-3"/>
                    </button>
                </Badge>
            ))}

            <Popover>
                <PopoverTrigger>
                    <Button variant="outline" size="sm" className="h-7 text-xs">
                        + Filter
                    </Button>
                </PopoverTrigger>
                <PopoverContent className="w-80" align="start">
                    <div className="space-y-3">
                        <div className="space-y-1">
                            <p className="text-xs font-medium">Field</p>
                            <Select defaultValue={newField} onValueChange={setNewField}>
                                <SelectTrigger className="h-8 text-xs">
                                    <SelectValue/>
                                </SelectTrigger>
                                <SelectContent>
                                    {FIELD_OPTIONS.map((f) => (
                                        <SelectItem key={f} value={f} className="text-xs">
                                            {f}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>

                        <div className="space-y-1">
                            <p className="text-xs font-medium">Type</p>
                            <Select defaultValue={newType} onValueChange={(v) => setNewType(v as FilterType)}>
                                <SelectTrigger className="h-8 text-xs">
                                    <SelectValue/>
                                </SelectTrigger>
                                <SelectContent>
                                    {experimentalMode && (
                                        <>
                                            <SelectItem value="EXISTS" className="text-xs">EXISTS (CLPP)</SelectItem>
                                            <SelectItem value="NEXISTS" className="text-xs">NEXISTS (CLPP)</SelectItem>
                                        </>
                                    )}
                                    <SelectItem value="EQUALS" className="text-xs">Equals</SelectItem>
                                    <SelectItem value="NOT_EQUALS" className="text-xs">Not Equals</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>

                        {("EXISTS" !== newType && "NEXISTS" !== newType) && (
                            <div className="space-y-1">
                                <p className="text-xs font-medium">Value</p>
                                <Input
                                    value={newValue}
                                    onChange={(e) => setNewValue(e.target.value)}
                                    className="h-8 text-xs"
                                    placeholder="Filter value..."
                                />
                            </div>
                        )}

                        {("EXISTS" === newType || "NEXISTS" === newType) && experimentalMode && (
                            <div className="rounded-md border border-yellow-300 bg-yellow-50 p-2">
                                <p className="text-xs text-yellow-800">
                                    Warning: EXISTS queries are not yet supported by the search backend.
                                    Results may be empty.
                                </p>
                            </div>
                        )}

                        <Button size="sm" onClick={handleAdd} className="w-full">
                            Add Filter
                        </Button>
                    </div>
                </PopoverContent>
            </Popover>
        </div>
    );
};


export {FilterBar};
export type {Filter, FilterType};
export default FilterBar;

