7	export interface SharedNodeWarning {
8	    variableIndex: number;
9	    types: Set<string>;
10	    logtypes: string[];
11	    message: string;
12	}
13	
14	/**
15	 * Counts the number of %VAR% placeholders in a logtype template string.
16	 * Variables are encoded as %VAR% in log-surgeon/CLP-S logtype templates.
17	 *
18	 * @param template
19	 */
20	function countVariables (template: string): number {
21	    const matches = template.match(/%VAR%/g);
22	    return matches ?
23	        matches.length :
24	        0;
25	}
26	
27	/**
28	 * Analyzes logtypes to detect shared nodes — variables at the same index
29	 * position that appear in multiple logtypes. When a shared node has
30	 * inconsistent types, it indicates a deduplication trap in the schema tree
31	 * that can cause ambiguous query results.
32	 *
33	 * @param logtypes
34	 */
35	function analyzeSharedNodes (
36	    logtypes: Array<{logtype: string; template: string; variables: Array<{index: number; type: string}>}>,
37	): SharedNodeWarning[] {
38	    const indexMap = new Map<number, Array<{logtype: string; type: string}>>();
39	
40	    for (const entry of logtypes) {
41	        for (const v of entry.variables) {
42	            if (!indexMap.has(v.index)) {
43	                indexMap.set(v.index, []);
44	            }
45	            indexMap.get(v.index)!.push({logtype: entry.logtype, type: v.type});
46	        }
47	    }
48	
49	    const warnings: SharedNodeWarning[] = [];
50	    for (const [index, occurrences] of indexMap) {
51	        if (1 < occurrences.length) {
52	            const types = new Set(occurrences.map((o) => o.type));
53	            if (1 < types.size) {
54	                warnings.push({
55	                    variableIndex: index,
56	                    types,
57	                    logtypes: occurrences.map((o) => o.logtype),
58	                    message: `Variable at position ${index} appears in ${occurrences.length} logtypes with inconsistent types (${[...types].join(", ")}). This creates a shared node in the schema tree that may cause ambiguous query results.`,
59	                });
60	            }
61	        }
62	    }
63	
64	    return warnings;
65	}
66	
67	export {
68	    analyzeSharedNodes, countVariables,
69	};
