import {
    useMutation,
    useQueryClient,
} from "@tanstack/react-query";
import type {AppType} from "@webui/server/hono-app";
import {hc} from "hono/client";

import {Button} from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {Input} from "@/components/ui/input";
import {Label} from "@/components/ui/label";
import {Textarea} from "@/components/ui/textarea";


type SchemaRecord = {
    id: string;
    name: string;
    content: string;
    createdAt: string;
    updatedAt: string;
};

const api = hc<AppType>("/");

const SchemaDialog = ({mode, schema}: {
    mode: "add" | "edit";
    schema?: SchemaRecord;
}) => {
    const queryClient = useQueryClient();
    const isEdit = "edit" === mode;

    const mutation = useMutation({
        mutationFn: async (data: {name: string; content: string}) => {
            if (isEdit && schema) {
                void api.api.schemas[":id"].$put({
                    param: {id: schema.id},
                    json: data,
                });
            } else {
                void api.api.schemas.$post({json: data});
            }
        },
        onSuccess: () => {
            void queryClient.invalidateQueries({queryKey: ["schemas"]});
        },
    });

    const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const formData = new FormData(e.currentTarget);
        mutation.mutate({
            name: formData.get("name") as string,
            content: formData.get("content") as string,
        });
    };

    return (
        <Dialog>
            <DialogTrigger asChild={true}>
                <Button size={"sm"}>{isEdit ?
                    "Edit" :
                    "Add Schema"}</Button>
            </DialogTrigger>
            <DialogContent className={"sm:max-w-lg"}>
                <DialogHeader>
                    <DialogTitle>{isEdit ?
                        "Edit Schema" :
                        "Add Schema"}</DialogTitle>
                </DialogHeader>
                <form
                    className={"space-y-4"}
                    onSubmit={handleSubmit}
                >
                    <div className={"space-y-2"}>
                        <Label htmlFor={"name"}>Name</Label>
                        <Input
                            defaultValue={isEdit ?
                                schema?.name :
                                ""}
                            id={"name"}
                            name={"name"}
                            placeholder={"hive-24hr-schema"}
                            required={true}/>
                    </div>
                    <div className={"space-y-2"}>
                        <Label htmlFor={"content"}>Schema Content</Label>
                        <Textarea
                            className={"min-h-48 font-mono text-sm"}
                            defaultValue={isEdit ?
                                schema?.content :
                                ""}
                            id={"content"}
                            name={"content"}
                            placeholder={"// Log-surgeon schema rules\ntimestamp :timestamp\nlevel :level"}
                            required={true}/>
                    </div>
                    <div className={"flex justify-end"}>
                        <Button
                            disabled={mutation.isPending}
                            type={"submit"}
                        >
                            {mutation.isPending ?
                                "Saving..." :
                                "Save"}
                        </Button>
                    </div>
                </form>
            </DialogContent>
        </Dialog>
    );
};

export default SchemaDialog;

