import {
    useMutation,
    useQueryClient,
} from "@tanstack/react-query";
import type {AppType} from "@webui/server/hono-app";
import {hc} from "hono/client";

import {Button} from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {Input} from "@/components/ui/input";
import {Label} from "@/components/ui/label";
import {Textarea} from "@/components/ui/textarea";


type SchemaRecord = {
    id: string;
    name: string;
    content: string;
    createdAt: string;
    updatedAt: string;
};

const api = hc<AppType>("/");

const SchemaDialog = ({mode, schema}: {
    mode: "add" | "edit";
    schema?: SchemaRecord;
}) => {
    const queryClient = useQueryClient();
    const isEdit = "edit" === mode;

    const mutation = useMutation({
        mutationFn: async (data: {name: string; content: string}) => {
            if (isEdit && schema) {
                void api.api.schemas[":id"].$put({
                    param: {id: schema.id},
                    json: data,
                });
            } else {
                void api.api.schemas.$post({json: data});
            }
        },
        onSuccess: () => {
            void queryClient.invalidateQueries({queryKey: ["schemas"]});
        },
    });

    const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const formData = new FormData(e.currentTarget);
        mutation.mutate({
            name: formData.get("name") as string,
            content: formData.get("content") as string,
        });
    };

    return (
        <Dialog>
            <DialogTrigger asChild={true}>
                <Button size={"sm"}>{isEdit ?
                    "Edit" :
                    "Add Schema"}</Button>
            </DialogTrigger>
            <DialogContent className={"sm:max-w-lg"}>
                <DialogHeader>
                    <DialogTitle>{isEdit ?
                        "Edit Schema" :
                        "Add Schema"}</DialogTitle>
                </DialogHeader>
                <form
                    className={"space-y-4"}
                    onSubmit={handleSubmit}
                >
                    <div className={"space-y-2"}>
                        <Label htmlFor={"name"}>Name</Label>
                        <Input
                            defaultValue={isEdit ?
                                schema?.name :
                                ""}
                            id={"name"}
                            name={"name"}
                            placeholder={"hive-24hr-schema"}
                            required={true}/>
                    </div>
                    <div className={"space-y-2"}>
                        <Label htmlFor={"content"}>Schema Content</Label>
                        <Textarea
                            className={"min-h-48 font-mono text-sm"}
                            defaultValue={isEdit ?
                                schema?.content :
                                ""}
                            id={"content"}
                            name={"content"}
                            placeholder={"// Log-surgeon schema rules\ntimestamp :timestamp\nlevel :level"}
                            required={true}/>
                    </div>
                    <div className={"flex justify-end"}>
                        <Button
                            disabled={mutation.isPending}
                            type={"submit"}
                        >
                            {mutation.isPending ?
                                "Saving..." :
                                "Save"}
                        </Button>
                    </div>
                </form>
            </DialogContent>
        </Dialog>
    );
};

export default SchemaDialog;

import {
    useMutation,
    useQuery,
    useQueryClient,
} from "@tanstack/react-query";
import type {AppType} from "@webui/server/hono-app";
import {hc} from "hono/client";

import {Button} from "@/components/ui/button";
import {
    Card,
    CardContent,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import {Input} from "@/components/ui/input";
import {Label} from "@/components/ui/label";
import {ScrollArea} from "@/components/ui/scroll-area";

import SchemaDialog from "./schema-dialog";


type SchemaRecord = {
    id: string;
    name: string;
    content: string;
    createdAt: string;
    updatedAt: string;
};

const api = hc<AppType>("/");

const SCHEMA_PREVIEW_LEN = 80;

const SchemaLibrary = () => {
    const queryClient = useQueryClient();
    const {data: schemas = [], isLoading} = useQuery({
        queryKey: ["schemas"],
        queryFn: async () => {
            const res = await api.api.schemas.$get();
            return res.json() as Promise<SchemaRecord[]>;
        },
    });

    const deleteMutation = useMutation({
        mutationFn: async (id: string) => {
            void api.api.schemas[":id"].$delete({param: {id}});
        },
        onSuccess: () => {
            void queryClient.invalidateQueries({queryKey: ["schemas"]});
        },
    });

    return (
        <Card>
            <CardHeader className={"flex flex-row items-center justify-between"}>
                <CardTitle className={"text-base"}>Saved Schemas</CardTitle>
                <SchemaDialog mode={"add"}/>
            </CardHeader>
            <CardContent>
                {isLoading && <p className={"text-sm text-muted-foreground"}>Loading...</p>}
                {0 === schemas.length && !isLoading && (
                    <p className={"text-sm text-muted-foreground"}>
                        No schemas saved yet. Click &ldquo;Add Schema&rdquo; to create one.
                    </p>
                )}
                <ScrollArea className={"max-h-64"}>
                    <div className={"space-y-2"}>
                        {schemas.map((schema) => (
                            <div
                                className={"flex items-center justify-between rounded-md border p-3"}
                                key={schema.id}
                            >
                                <div className={"min-w-0 flex-1"}>
                                    <p className={"truncate text-sm font-medium"}>
                                        {schema.name}
                                    </p>
                                    <p className={"truncate text-xs text-muted-foreground"}>
                                        {schema.content.slice(0, SCHEMA_PREVIEW_LEN)}
                                        {SCHEMA_PREVIEW_LEN < schema.content.length ?
                                            "..." :
                                            ""}
                                    </p>
                                </div>
                                <div className={"flex gap-2"}>
                                    <SchemaDialog
                                        mode={"edit"}
                                        schema={schema}/>
                                    <Button
                                        size={"sm"}
                                        variant={"ghost"}
                                        onClick={() => {
                                            deleteMutation.mutate(schema.id);
                                        }}
                                    >
                                        Delete
                                    </Button>
                                </div>
                            </div>
                        ))}
                    </div>
                </ScrollArea>
            </CardContent>
        </Card>
    );
};

export {SchemaLibrary};
export default SchemaLibrary;

export interface VariableOccurrence {
    index: number;
    logtype: string;
    type: "string" | "int" | "float";
}

export interface SharedNodeWarning {
    variableIndex: number;
    types: Set<string>;
    logtypes: string[];
    message: string;
}

const countVariables = (template: string): number => {
    const matches = template.match(/%VAR%/g);
    return matches ?
        matches.length :
        0;
};

const analyzeSharedNodes = (
    logtypes: Array<{logtype: string; template: string;
        variables: Array<{index: number; type: string}>}>,
): SharedNodeWarning[] => {
    const indexMap = new Map<number, Array<{logtype: string; type: string}>>();

    for (const entry of logtypes) {
        for (const v of entry.variables) {
            if (!indexMap.has(v.index)) {
                indexMap.set(v.index, []);
            }
            const bucket = indexMap.get(v.index);
            if (bucket) {
                bucket.push({logtype: entry.logtype, type: v.type});
            }
        }
    }

    const warnings: SharedNodeWarning[] = [];
    for (const [index, occurrences] of indexMap) {
        if (1 < occurrences.length) {
            const types = new Set(occurrences.map((o) => o.type));
            if (1 < types.size) {
                const typeList = [...types].join(", ");
                warnings.push({
                    variableIndex: index,
                    types,
                    logtypes: occurrences.map((o) => o.logtype),
                    message: `Variable at position ${index} appears in ` +
                        `${occurrences.length} logtypes with inconsistent ` +
                        `types (${typeList}). This creates a shared node ` +
                        "in the schema tree that may cause ambiguous " +
                        "query results.",
                });
            }
        }
    }

    return warnings;
};

export {
    analyzeSharedNodes, countVariables,
};

import {
    Tabs,
    TabsContent,
    TabsList,
    TabsTrigger,
} from "@/components/ui/tabs";
import PatternsTab from "@/features/clpp/components/patterns-tab";
import SchemaTab from "@/features/clpp/components/schema-tab";
import StatsTab from "@/features/clpp/components/stats-tab";
import {useClppSettingsStore} from "@/features/clpp/stores/clpp-settings-store";


/**
 *
 * @param root0
 * @param root0.children
 */
const ExploreTabs = ({children}: {children: React.ReactNode}) => {
    const experimentalMode = useClppSettingsStore((s) => s.experimentalMode);

    return (
        <Tabs defaultValue={"logs"}>
            <TabsList>
                <TabsTrigger value={"logs"}>Logs</TabsTrigger>
                {experimentalMode && (
                    <>
                        <TabsTrigger value={"patterns"}>Patterns</TabsTrigger>
                        <TabsTrigger value={"schema"}>Schema</TabsTrigger>
                        <TabsTrigger value={"stats"}>Stats</TabsTrigger>
                    </>
                )}
            </TabsList>
            <TabsContent value={"logs"}>
                {children}
            </TabsContent>
            {experimentalMode && (
                <>
                    <TabsContent value={"patterns"}>
                        <PatternsTab/>
                    </TabsContent>
                    <TabsContent value={"schema"}>
                        <SchemaTab/>
                    </TabsContent>
                    <TabsContent value={"stats"}>
                        <StatsTab/>
                    </TabsContent>
                </>
            )}
        </Tabs>
    );
};

export default ExploreTabs;

