28	 */
29	const analyzeSharedNodes = (
30	    logtypes: Array<{logtype: string;
31	        template: string;
32	        variables: Array<{index: number; type: string}>;}>,
33	): SharedNodeWarning[] => {
34	    const indexMap = new Map<number, Array<{logtype: string; type: string}>>();
35	
36	    for (const entry of logtypes) {
37	        for (const v of entry.variables) {
38	            if (!indexMap.has(v.index)) {
39	                indexMap.set(v.index, []);
40	            }
41	            const bucket = indexMap.get(v.index);
42	            if (bucket) {
43	                bucket.push({logtype: entry.logtype, type: v.type});
44	            }
45	        }
46	    }
47	
48	    const warnings: SharedNodeWarning[] = [];
49	    for (const [index, occurrences] of indexMap) {
50	        if (1 < occurrences.length) {
51	            const types = new Set(occurrences.map((o) => o.type));
52	            if (1 < types.size) {
53	                const typeList = [...types].join(", ");
54	                warnings.push({
55	                    variableIndex: index,
56	                    types,
57	                    logtypes: occurrences.map((o) => o.logtype),
58	                    message: `Variable at position ${index} appears in ` +
59	                        `${occurrences.length} logtypes with inconsistent ` +
60	                        `types (${typeList}). This creates a shared node ` +
61	                        "in the schema tree that may cause ambiguous " +
62	                        "query results.",
63	                });
64	            }
65	        }
66	    }
67	
68	    return warnings;
69	};
70	
71	export {
72	    analyzeSharedNodes, countVariables,
73	};
