import {CLP_QUERY_ENGINES} from "@webui/common/config";

import {SETTINGS_QUERY_ENGINE} from "../../../config";
import usePrestoSearchState from "../SearchState/Presto";
import {PRESTO_SQL_INTERFACE} from "../SearchState/Presto/typings";
import NativeControls from "./Native/NativeControls";
import FreeformControls from "./Presto/Freeform/FreeformControls";
import GuidedControls from "./Presto/Guided/GuidedControls";


/**
 * Prevents the default behavior to avoid page reload when submitting query.
 *
 * @param ev
 */
const handleSubmit = (ev: React.FormEvent<HTMLFormElement>) => {
    ev.preventDefault();
};

/**
 * Renders controls for submitting queries and the query status.
 *
 * @return
 */
const SearchControls = () => {
    const sqlInterface = usePrestoSearchState((state) => state.sqlInterface);
    const isPrestoGuided = sqlInterface === PRESTO_SQL_INTERFACE.GUIDED;

    let controls;
    if (SETTINGS_QUERY_ENGINE !== CLP_QUERY_ENGINES.PRESTO) {
        controls = <NativeControls/>;
    } else if (isPrestoGuided) {
        controls = <GuidedControls/>;
    } else {
        controls = <FreeformControls/>;
    }

    return (
        <form onSubmit={handleSubmit}>
            {controls}
        </form>
    );
};

export default SearchControls;

import {
    Card,
    CardContent,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import {Label} from "@/components/ui/label";
import {Separator} from "@/components/ui/separator";
import {Switch} from "@/components/ui/switch";
import {SchemaLibrary} from "@/features/clpp/components/schema-library";
import {useClppSettingsStore} from "@/features/clpp/stores/clpp-settings-store";


/**
 *
 */
const SettingsPage = () => {
    const experimentalMode = useClppSettingsStore((s) => s.experimentalMode);
    const setExperimentalMode = useClppSettingsStore((s) => s.setExperimentalMode);

    return (
        <div className={"mx-auto max-w-2xl space-y-6 p-6"}>
            <Card>
                <CardHeader>
                    <CardTitle>Settings</CardTitle>
                </CardHeader>
                <CardContent className={"space-y-6"}>
                    <div className={"space-y-2"}>
                        <h3 className={"text-sm font-medium"}>General</h3>
                        <Separator/>
                        <div className={"flex items-center gap-3 pt-2"}>
                            <Switch
                                checked={experimentalMode}
                                onCheckedChange={setExperimentalMode}/>
                            <Label>Experimental Mode</Label>
                        </div>
                    </div>
                </CardContent>
            </Card>
            <div className={"space-y-2"}>
                <h3 className={"text-sm font-medium"}>Schema Library</h3>
                <Separator/>
                <SchemaLibrary/>
            </div>
        </div>
    );
};


export default SettingsPage;

