    }

    if (!data) {
        return <div className={"p-4 text-sm text-muted-foreground"}>No logtype data available.</div>;
    }

    const filtered = data.logtypes.filter(
        (lt) => lt.logtype.toLowerCase().includes(search.toLowerCase()) ||
            lt.template.toLowerCase().includes(search.toLowerCase()),
    );

    return (
        <div className={"flex flex-col gap-4"}>
            {0 < data.sharedNodeWarnings.length && (
                <div className={"rounded-md border border-yellow-300 bg-yellow-50 p-3"}>
                    <p className={"text-sm font-medium text-yellow-800"}>Shared Node Warnings</p>
                    <ul className={"mt-1 list-inside list-disc text-sm text-yellow-700"}>
                        {data.sharedNodeWarnings.map((w, i) => (
                            <li key={i}>
                                {w.message}
                            </li>
                        ))}
                    </ul>
                </div>
            )}

            <Input
                placeholder={"Search logtypes..."}
                value={search}
                onChange={(e) => {
                    setSearch(e.target.value);
                }}/>

            <div className={"text-sm text-muted-foreground"}>
                {filtered.length}
                {" "}
                logtype
                {1 !== filtered.length ?
                    "s" :
                    ""}
                {" "}
                |
                {data.totalCount.toLocaleString()}
                {" "}
                total events
            </div>

            <ScrollArea className={"h-[calc(100vh-320px)]"}>
                <Table>
                    <TableHeader>
                        <TableRow>
                            <TableHead className={"w-12"}/>
                            <TableHead>Logtype</TableHead>
                            <TableHead className={"text-right"}>Count</TableHead>
                            <TableHead>Template</TableHead>
                        </TableRow>
                    </TableHeader>
                    <TableBody>
                        {filtered.map((lt) => {
                            const isExpanded = expandedLogtype === lt.logtype;
                            return (
                                <Collapsible
                                    asChild={true}
                                    key={lt.logtype}
                                    open={isExpanded}
                                    onOpenChange={() => {
                                        setExpandedLogtype(isExpanded ?
                                            null :
                                            lt.logtype);
                                    }}
                                >
                                    <TableRow className={"cursor-pointer"}>
                                        <TableCell>
                                            <CollapsibleTrigger asChild={true}>
                                                <button className={"text-muted-foreground hover:text-foreground"}>
                                                    {isExpanded ?
                                                        "▼" :
                                                        "▶"}
                                                </button>
                                            </CollapsibleTrigger>
                                        </TableCell>
                                        <TableCell className={"font-mono text-xs"}>
                                            {lt.logtype}
                                        </TableCell>
                                        <TableCell className={"text-right"}>
                                            {lt.count.toLocaleString()}
                                        </TableCell>
                                        <TableCell className={"max-w-md truncate font-mono text-xs"}>
                                            {lt.template}
                                        </TableCell>
                                    </TableRow>
                                    {isExpanded && (
                                        <TableRow>
                                            <TableCell
                                                className={"bg-muted/50 px-8 py-3"}
                                                colSpan={4}
                                            >
                                                <CollapsibleContent>
                                                    <div className={"space-y-2"}>
                                                        <p className={"text-xs font-medium"}>
                                                            Variables (
                                                            {lt.variables.length}
                                                            )
                                                        </p>
                                                        <div className={"flex flex-wrap gap-2"}>
                                                            {lt.variables.map((v) => (
                                                                <Badge
                                                                    className={VARIABLE_TYPE_COLORS[v.type] ?? ""}
                                                                    key={v.index}
                                                                    variant={"outline"}
                                                                >
                                                                    #
                                                                    {v.index}
                                                                    {" "}
                                                                    {v.type}
                                                                </Badge>
                                                            ))}
                                                        </div>
                                                        <Separator/>
                                                        <p className={"text-xs text-muted-foreground"}>
                                                            Template:
                                                            {" "}
                                                            <code className={"text-foreground"}>
                                                                {lt.template}
                                                            </code>
                                                        </p>
                                                    </div>
                                                </CollapsibleContent>
                                            </TableCell>
                                        </TableRow>
                                    )}
                                </Collapsible>
                            );
                        })}
                    </TableBody>
                </Table>
            </ScrollArea>
        </div>
    );
};


export {PatternsTab};
export default PatternsTab;

