                                                            <code className={"text-foreground"}>
                                                                {lt.template}
                                                            </code>
                                                        </p>
                                                    </div>
                                                </CollapsibleContent>
                                            </TableCell>
                                        </TableRow>
                                    )}
                                </Collapsible>
                            );
                        })}
                    </TableBody>
                </Table>
            </ScrollArea>
        </div>
    );
};


export {PatternsTab};
export default PatternsTab;

