import {useState} from "react";

import {useQuery} from "@tanstack/react-query";
import type {AppType} from "@webui/server/hono-app";
import {hc} from "hono/client";

import {Badge} from "@/components/ui/badge";
import {
    Collapsible,
    CollapsibleContent,
    CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {Input} from "@/components/ui/input";
import {ScrollArea} from "@/components/ui/scroll-area";
import {Separator} from "@/components/ui/separator";
import {useClppSettingsStore} from "@/features/clpp/stores/clpp-settings-store";


type SchemaTreeNode = {
    id: string;
    key: string;
    type: "string" | "int" | "float" | "object";
    count: number;
    children: SchemaTreeNode[];
};

type FieldItem = {
    name: string;
    type: "string" | "int" | "float" | "object";
    count: number;
    isSharedNode: boolean;
};

const api = hc<AppType>("/");

const TYPE_ICONS: Record<string, string> = {
    string: "Aa",
    int: "#",
    float: "~",
    object: "{}",
};

const TYPE_COLORS: Record<string, string> = {
    string: "text-green-600",
    int: "text-blue-600",
    float: "text-purple-600",
    object: "text-gray-600",
};

/**
 * Flattens the schema tree into a list of field items.
 *
 * @param node
 * @param parentPath
 * @param isShared
 */
const flattenTree = (
    node: SchemaTreeNode,
    parentPath: string = "",
    isShared: boolean = false,
): FieldItem[] => {
    const path = parentPath ?
        `${parentPath}.${node.key}` :
        node.key;
    const items: FieldItem[] = [];

    if ("object" !== node.type) {
        items.push({
            name: path,
            type: node.type,
            count: node.count,
            isSharedNode: isShared,
        });
    }

    for (const child of node.children) {
        items.push(...flattenTree(child, path, isShared));
    }

    return items;
};

/**
 * A single field row with expand/collapse for top values.
 *
 * @param root0
 * @param root0.field
 * @param root0.field
 * @param root0.isSelected
 * @param root0.onToggleSelect
 */
const FieldRow = ({isSelected, onToggleSelect, field}: {
    field: FieldItem;
    isSelected: boolean;
    onToggleSelect: (name: string) => void;
}) => {
    const [isOpen, setIsOpen] = useState(false);

    return (
        <Collapsible
            open={isOpen}
            onOpenChange={setIsOpen}
        >
            <div className={"flex items-center gap-1.5 rounded-sm px-2 py-1 hover:bg-muted/50"}>
                <CollapsibleTrigger asChild={true}>
                    <button className={"w-3 text-[10px] text-muted-foreground hover:text-foreground"}>
                        {isOpen ?
                            "▼" :
                            "▶"}
                    </button>
                </CollapsibleTrigger>
                <span className={`text-xs font-medium ${TYPE_COLORS[field.type] ?? ""}`}>
                    {TYPE_ICONS[field.type] ?? "?"}
                </span>
                <span
                    className={"flex-1 cursor-pointer truncate text-xs" +
                        (isSelected ?
                            " font-bold" :
                            "")}
                    onClick={() => {
                        onToggleSelect(field.name);
                    }}
                >
                    {field.name}
                </span>
                {field.isSharedNode && (
                    <span
                        className={"text-[10px] text-yellow-600"}
                        title={"Shared node — may cause ambiguous queries"}
                    >
                        [!]
                    </span>
                )}
                <span className={"text-[10px] text-muted-foreground"}>
                    {field.count.toLocaleString()}
                </span>
            </div>
            <CollapsibleContent>
                <div
                    className={"ml-6 space-y-0.5 border-l " +
                        "px-2 py-1 text-xs text-muted-foreground"}
                >
                    <p>
                        Type:
                        {field.type}
                    </p>
                    <p>
                        Count:
                        {field.count.toLocaleString()}
                    </p>
                    {field.isSharedNode && (
                        <p className={"text-yellow-700"}>
                            Warning: shared node
                            {" "}
                            — deduplication trap
                        </p>
                    )}
                </div>
            </CollapsibleContent>
        </Collapsible>
    );
};

/**
 * Kibana Discover-style field browser sidebar.
 *
 * Two sections:
 * - "Selected fields": fields that appear as columns in the results table
 * - "Available fields": all other fields from the schema tree
 *
 * When experimental mode is OFF, shows only standard indexed fields.
 * When experimental mode is ON, adds "LOGTYPE FIELDS [CLPP]" from Schema Tree API.
 *
 * @param root0
 * @param root0.selectedFields
 * @param root0.onToggleField
 */
const FieldBrowser = ({
    selectedFields,
    onToggleField,
}: {
    selectedFields: string[];
    onToggleField: (name: string) => void;
}) => {
    const [search, setSearch] = useState("");
    const experimentalMode = useClppSettingsStore((s) => s.experimentalMode);

    const {data: treeData} = useQuery({
        queryKey: ["schema-tree"],
        queryFn: async () => {
            const res = await api.api["schema-tree"].$get({
                query: {archive_id: "latest"},
            });

            return res.json();
        },
        enabled: experimentalMode,
    });

    const standardFields: FieldItem[] = [
        {name: "timestamp", type: "string", count: 0, isSharedNode: false},
        {name: "service", type: "string", count: 0, isSharedNode: false},
        {name: "level", type: "string", count: 0, isSharedNode: false},
    ];

    const clppFields: FieldItem[] = treeData?.tree ?
        flattenTree(treeData.tree) :
        [];

    const allFields = experimentalMode ?
        [...standardFields,
            ...clppFields] :
        standardFields;

    const filtered = allFields.filter(
        (f) => f.name.toLowerCase().includes(search.toLowerCase()),
    );

    const selected = filtered.filter((f) => selectedFields.includes(f.name));
    const available = filtered.filter((f) => !selectedFields.includes(f.name));

    return (
        <div className={"flex h-full w-60 flex-col border-r bg-background"}>
            <div className={"p-2"}>
                <Input
                    className={"h-7 text-xs"}
                    placeholder={"Filter fields..."}
                    value={search}
                    onChange={(e) => {
                        setSearch(e.target.value);
                    }}/>
            </div>

            <ScrollArea className={"flex-1"}>
                {0 < selected.length && (
                    <div>
                        <p
                            className={"px-2 py-1 text-[10px] " +
                                "font-semibold uppercase " +
                                "text-muted-foreground"}
                        >
                            Selected Fields
                        </p>
                        {selected.map((f) => (
                            <FieldRow
                                field={f}
                                isSelected={true}
                                key={f.name}
                                onToggleSelect={onToggleField}/>
                        ))}
                        <Separator className={"my-1"}/>
                    </div>
                )}

                <div>
                    <p className={"px-2 py-1 text-[10px] font-semibold uppercase text-muted-foreground"}>
                        Available Fields
                    </p>
                    {available.map((f) => (
                        <FieldRow
                            field={f}
                            isSelected={false}
                            key={f.name}
                            onToggleSelect={onToggleField}/>
                    ))}
                </div>

                {experimentalMode && 0 < clppFields.length && (
                    <>
                        <Separator className={"my-1"}/>
                        <div className={"px-2 py-1"}>
                            <Badge
                                className={"text-[10px]"}
                                variant={"outline"}
                            >
                                LOGTYPE FIELDS [CLPP]
                            </Badge>
                        </div>
                    </>
                )}
            </ScrollArea>
        </div>
    );
};


export {FieldBrowser};
export default FieldBrowser;

import {
    useMutation,
    useQueryClient,
} from "@tanstack/react-query";
import type {AppType} from "@webui/server/hono-app";
import {hc} from "hono/client";

import {Button} from "@/components/ui/button";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "@/components/ui/dialog";
import {Input} from "@/components/ui/input";
import {Label} from "@/components/ui/label";
import {Textarea} from "@/components/ui/textarea";


type SchemaRecord = {
    id: string;
    name: string;
    content: string;
    createdAt: string;
    updatedAt: string;
};

const api = hc<AppType>("/");

/**
 *
 * @param root0
 * @param root0.mode
 * @param root0.schema
 */
const SchemaDialog = ({mode, schema}: {
    mode: "add" | "edit";
    schema?: SchemaRecord;
}) => {
    const queryClient = useQueryClient();
    const isEdit = "edit" === mode;

    const mutation = useMutation({
        mutationFn: async (data: {name: string; content: string}) => {
            if (isEdit && schema) {
                await api.api.schemas[":id"].$put({
                    param: {id: schema.id},
                    json: data,
                });
            } else {
                await api.api.schemas.$post({json: data});
            }
        },
        onSuccess: async () => {
            await queryClient.invalidateQueries({queryKey: ["schemas"]});
        },
    });

    const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const formData = new FormData(e.currentTarget);
        mutation.mutate({
            name: formData.get("name") as string,
            content: formData.get("content") as string,
        });
    };

    return (
        <Dialog>
            <DialogTrigger asChild={true}>
                <Button size={"sm"}>
                    {isEdit ?
                        "Edit" :
                        "Add Schema"}
                </Button>
            </DialogTrigger>
            <DialogContent className={"sm:max-w-lg"}>
                <DialogHeader>
                    <DialogTitle>
                        {isEdit ?
                            "Edit Schema" :
                            "Add Schema"}
                    </DialogTitle>
                </DialogHeader>
                <form
                    className={"space-y-4"}
                    onSubmit={handleSubmit}
                >
                    <div className={"space-y-2"}>
                        <Label htmlFor={"name"}>Name</Label>
                        <Input
                            id={"name"}
                            name={"name"}
                            placeholder={"hive-24hr-schema"}
                            required={true}
                            defaultValue={isEdit ?
                                schema?.name :
                                ""}/>
                    </div>
                    <div className={"space-y-2"}>
                        <Label htmlFor={"content"}>Schema Content</Label>
                        <Textarea
                            className={"min-h-48 font-mono text-sm"}
